/// `net_ids` is the comma-joined player NetId list, same shape as
/// `character_ids`; the two pair positionally to build the run's roster.
/// `start_time` is the game's `StartTime` run id (0 when the shim's read
/// failed; the identity stays unknown).
///
/// # Safety
/// Non-null pointers cover initialized readable bytes through a terminating NUL
/// in one allocation, with a total range shorter than `isize::MAX` bytes. Each
/// range remains readable and unmodified throughout this call.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn spire_profiler_run_started(
    character_ids: *const c_char,
    ascension: i32,
    game_mode: *const c_char,
    seed: *const c_char,
    continued: i32,
    net_ids: *const c_char,
    start_time: i64,
) {
    // SAFETY: pointer arguments satisfy this export's C contract.
    unsafe {
        with_c_str(character_ids, |character_ids| {
            with_c_str(game_mode, |game_mode| {
                with_c_str(seed, |seed| {
                    with_c_str(net_ids, |net_ids| {
                        contain("spire_profiler_run_started", (), || {
                            events::run_started(
                                character_ids,
                                ascension,
                                game_mode,
                                seed,
                                continued,
                                net_ids,
                                start_time,
                            );
                        });
                    });
                });
            });
        })
    };
}

