#[cfg(test)]
mod tests {
    use std::ffi::CString;
    use std::fs;

    use super::*;
    use crate::data::state::STATE;

    fn unique_dir(label: &str) -> (std::path::PathBuf, CString) {
        let dir = crate::test_util::unique_dir(label);
        let c_dir = CString::new(
            dir.to_str()
                .expect("the checkout path and fixture label must be UTF-8 for the ABI"),
        )
        .expect("filesystem directory names cannot contain NUL");
        (dir, c_dir)
    }

    #[test]
    fn exported_surface_runs_the_self_test_pipeline() {
        let (base, c_base) = unique_dir("spire-profiler-abi-test");
        // SAFETY: the test forms valid C-string arguments for these exports.
        unsafe {
            spire_profiler_test_reset();
            spire_profiler_init(c_base.as_ptr());
            spire_profiler_self_test();
        }
        assert!(
            base.join("runs.jsonl").exists(),
            "expected runs.jsonl to exist"
        );
        // The combat store: one file per combat, named by its id, under
        // its run's directory — the self-test's combat must be among them.
        let runs_dir = base.join("runs");
        assert!(
            runs_dir.is_dir(),
            "expected {runs_dir} to exist",
            runs_dir = runs_dir.display()
        );
        let mut found = false;
        for run in fs::read_dir(&runs_dir).expect("runs dir readable") {
            let run_dir = run.expect("entry readable").path();
            if !run_dir.is_dir() {
                continue;
            }
            for entry in fs::read_dir(&run_dir).expect("run dir readable") {
                let text = fs::read_to_string(entry.expect("entry readable").path())
                    .expect("combat file readable");
                if text.contains("SELF_TEST") {
                    found = true;
                }
            }
        }
        assert!(found, "the self-test combat must be in the store");
    }

    #[test]
    fn containment_swallows_a_panicking_core_function() {
        contain("spire_profiler_test_reset", (), || panic!("boom"));
        contain("spire_profiler_test_reset", (), || panic!("str payload"));
    }

    #[test]
    fn containment_does_not_drop_an_adversarial_panic_payload() {
        struct PanickingDrop;
        impl Drop for PanickingDrop {
            fn drop(&mut self) {
                panic!("payload destructor escaped containment");
            }
        }
        assert_eq!(
            contain("panic_payload", 17, || std::panic::panic_any(PanickingDrop)),
            17
        );
        assert_eq!(contain("success", 17, || 23), 23);
    }

    #[test]
    fn transfer_exports_contain_reentrant_state_borrows_and_reject_stale_epochs() {
        events::test_reset();
        STATE.with(|cell| {
            cell.borrow_mut().current = Some(crate::data::state::Combat {
                seq: 9,
                ..Default::default()
            });
        });
        let transfer = spire_profiler_source_transfer_begin(9);
        let destination = (9_u64 << 32) | (4 << 3) | 1;
        assert_eq!(
            spire_profiler_source_transfer_add(transfer, destination, 3),
            1
        );
        assert_eq!(spire_profiler_source_transfer_seal(transfer), 1);
        assert_eq!(spire_profiler_source_count(transfer), 1);
        STATE.with(|cell| {
            let _guard = cell.borrow_mut();
            assert_eq!(spire_profiler_source_count(transfer), -1);
            assert_eq!(spire_profiler_source_weight(transfer, 0), 0);
            assert_eq!(spire_profiler_source_destination(transfer, 0), 0);
            assert_eq!(spire_profiler_source_transfer_begin(9), 0);
            assert_eq!(spire_profiler_source_transfer_release(transfer), 0);
        });
        assert_eq!(spire_profiler_source_count(transfer), 1);
        assert_eq!(spire_profiler_source_weight(transfer, 0), 1);
        assert_eq!(spire_profiler_source_destination(transfer, 0), destination);
        STATE.with(|cell| {
            cell.borrow_mut()
                .current
                .as_mut()
                .expect("fixture combat exists")
                .seq = 10;
        });
        assert_eq!(spire_profiler_source_count(transfer), -1);
        assert_eq!(spire_profiler_source_transfer_release(transfer), 0);
        events::test_reset();
    }

    #[test]
    fn scroll_input_export_preserves_routing_and_recovers_from_corrupt_deltas() {
        let data = crate::test_util::unique_dir("spire-profiler-abi-scroll");
        events::test_reset();
        events::init(&data);
        STATE.with(|s| s.borrow_mut().run_ctx = Some(Default::default()));
        crate::ui::panel::dismiss();
        crate::ui::panel::toggle();
        crate::data::run_history::select("", 0, 1);
        crate::ui::run_panel::dismiss_run_manual();
        crate::ui::run_panel::toggle_run_manual();

        for invalid in [f64::NAN, f64::INFINITY, f64::NEG_INFINITY] {
            spire_profiler_scroll_input(0, 5, 1, invalid);
            spire_profiler_scroll_input(0, 0, 0, 12.5);
            spire_profiler_scroll_input(0, 0, 0, invalid);
            spire_profiler_scroll_input(1, 0, 0, -10.0);
            spire_profiler_scroll_input(1, 4, 0, invalid);
            spire_profiler_scroll_input(1, 4, 0, -2.5);
            spire_profiler_scroll_input(1, 4, 1, invalid);
            spire_profiler_scroll_input(7, 5, 1, 0.0);
            spire_profiler_scroll_input(7, 0, 0, invalid);
            assert_eq!(crate::ui::panel::take_queued_scroll(), 72.5);
            assert_eq!(crate::ui::run_panel::take_queued_scroll(), -72.5);
        }
        spire_profiler_scroll_input(0, 0, 0, f64::MAX);
        spire_profiler_scroll_input(1, 0, 0, -f64::MAX);
        assert_eq!(crate::ui::panel::take_queued_scroll(), f32::MAX);
        assert_eq!(crate::ui::run_panel::take_queued_scroll(), -f32::MAX);
        spire_profiler_scroll_input(0, 0, 0, 15.0);
        spire_profiler_scroll_input(1, 0, 0, -12.5);
        assert_eq!(crate::ui::panel::take_queued_scroll(), 15.0);
        assert_eq!(crate::ui::run_panel::take_queued_scroll(), -12.5);
    }

    #[test]
    fn panel_toggle_export_flips_panel_state_by_run_context() {
        let (_base, c_base) = unique_dir("spire-profiler-abi-toggle");
        let char_ids = CString::new("IRONCLAD").expect("no NUL");
        let mode = CString::new("Standard").expect("no NUL");
        let seed = CString::new("TOGGLE_SEED").expect("no NUL");
        let net_ids = CString::new("1").expect("no NUL");
        // SAFETY: the test forms valid C-string arguments for these exports.
        unsafe {
            spire_profiler_test_reset();
            spire_profiler_init(c_base.as_ptr());
        }
        // Outside a run the combat-panel toggle is the documented no-op.
        let before = crate::ui::panel::visible();
        spire_profiler_panel_toggle();
        assert_eq!(crate::ui::panel::visible(), before);
        // Inside a run the same export flips the panel.
        // SAFETY: the test forms valid C-string arguments for these exports.
        unsafe {
            spire_profiler_run_started(
                char_ids.as_ptr(),
                0,
                mode.as_ptr(),
                seed.as_ptr(),
                0,
                net_ids.as_ptr(),
                0,
            );
            spire_profiler_panel_toggle();
        }
        assert!(crate::ui::panel::visible());
        spire_profiler_panel_toggle();
        assert!(!crate::ui::panel::visible());
        // With the run-history screen open, the toggle routes to the run
        // panel's manual flag instead: every press flips it.
        // SAFETY: the test forms valid C-string arguments for these exports.
        unsafe {
            spire_profiler_run_history_select(seed.as_ptr(), 0, 1);
            spire_profiler_panel_toggle();
        }
        assert!(crate::ui::run_panel::run_manual_visible());
        spire_profiler_panel_toggle();
        assert!(!crate::ui::run_panel::run_manual_visible());
        spire_profiler_panel_toggle();
        assert!(crate::ui::run_panel::run_manual_visible());
        // The clear that precedes every screen entry resets the flag: the
        // panel starts closed on each visit.
        spire_profiler_scroll_input(1, 5, 1, 0.0);
        spire_profiler_run_history_clear();
        assert!(!crate::ui::run_panel::run_manual_visible());
        assert_eq!(crate::ui::run_panel::take_queued_scroll(), 0.0);
        // SAFETY: seed is a valid C string; the other arguments are scalars.
        unsafe {
            spire_profiler_run_history_select(seed.as_ptr(), 0, 1);
            spire_profiler_panel_toggle();
        }
        assert_eq!(crate::ui::run_panel::take_queued_scroll(), 0.0);
    }

    #[test]
    fn run_history_select_and_clear_exports_drive_the_selection() {
        let (base, c_base) = unique_dir("spire-profiler-abi-run-history");
        let seed = CString::new("SELF_TEST_SEED").expect("no NUL in seed");
        // SAFETY: the test forms valid C-string arguments for these exports.
        unsafe {
            spire_profiler_test_reset();
            spire_profiler_init(c_base.as_ptr());
            spire_profiler_self_test();
        }
        // Select the identity that traversed the ABI and persisted writer.
        let text = fs::read_to_string(base.join("runs.jsonl")).expect("runs.jsonl readable");
        let record: serde_json::Value =
            serde_json::from_str(text.lines().next().expect("a run line"))
                .expect("run line parses");
        let start = record["started_at"].as_i64().expect("started_at is i64");
        // SAFETY: the test forms valid C-string arguments for these exports.
        unsafe { spire_profiler_run_history_select(seed.as_ptr(), start, 1) };
        let view = crate::data::run_history::selected_view().expect("selection stored");
        assert_eq!(view.seed, "SELF_TEST_SEED");
        assert_eq!(view.character, "SELF_TEST_CHAR");
        assert_eq!(view.outcome, Some(RunOutcome::Victory));
        assert_eq!(view.combats.len(), 1);
        assert_eq!(view.combats[0].encounter, "SELF_TEST");

        spire_profiler_run_history_clear();
        assert!(crate::data::run_history::selected_view().is_none());
    }

    #[test]
    fn null_and_malformed_strings_become_unknown_without_retaining_foreign_bytes() {
        let (_base, c_base) = unique_dir("spire-profiler-abi-strings");
        // SAFETY: fixture buffers include readable NUL bytes and remain immutable during each call.
        unsafe {
            spire_profiler_test_reset();
            spire_profiler_init(c_base.as_ptr());
            let epoch = spire_profiler_combat_started(std::ptr::null(), c"\xff".as_ptr());
            assert_ne!(epoch, 0);
            for pointer in [std::ptr::null(), c"".as_ptr(), c"\xff".as_ptr()] {
                let source = spire_profiler_source_capture(epoch, 1, 1, pointer, 0, 0, 0);
                assert_eq!(spire_profiler_source_count(source), 1);
                assert_eq!(
                    spire_profiler_source_destination(source, 0),
                    (epoch << 32) | (4 << 3) | 1
                );
                assert_eq!(spire_profiler_source_transfer_release(source), 1);
            }
            STATE.with(|cell| {
                let state = cell.borrow();
                let combat = state.current.as_ref().expect("fixture combat exists");
                assert_eq!(
                    (combat.encounter_id.as_str(), combat.encounter_type.as_str()),
                    ("", "")
                );
            });
            assert_eq!(spire_profiler_combat_ended(epoch), 1);
        }
    }
}
